inline const FactoryPresetCategoryDefinition* findFactoryPresetCategory(const char* categoryId)
{
    if (categoryId == nullptr)
        return nullptr;

    for (const auto& category : kFactoryPresetCategories)
        if (std::strcmp(category.id, categoryId) == 0)
            return &category;

    return nullptr;
}

inline bool factoryPresetCategoryExists(const char* categoryId)
{
    return findFactoryPresetCategory(categoryId) != nullptr;
}

inline float getFactoryPresetCategoryMixFloor(const char* categoryId)
{
    if (const auto* category = findFactoryPresetCategory(categoryId))
        return category->mixFloor;

    return 0.48f;
}

